const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Cambodia';
  const startDate = '2016-08-01';
  const endDate = '2018-02-28'; // Up to and including Feb 28, 2018

  // Get Cambodia's administrative boundary
  let cambodia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', countryName));

  if (cambodia.size().getInfo() === 0) {
    console.log(`Error: Could not find ${countryName} in the GAUL dataset.`);
    console.log("C3"); // Calculation failure, as geometry is crucial.
    return;
  }

  cambodia = cambodia.first().geometry(); // Get the geometry of Cambodia

  // Determine an approximate split point for northern/southern Cambodia
  const bounds = cambodia.bounds().getInfo();
  if (!bounds || !bounds.coordinates || bounds.coordinates.length === 0) {
    console.log("Error: Could not get bounds for Cambodia.");
    console.log("C3");
    return;
  }
  const minLat = bounds.coordinates[0][0][1];
  const maxLat = bounds.coordinates[0][2][1];
  const splitLat = (minLat + maxLat) / 2; // Simple mid-latitude split

  // Create northern and southern regions
  const northernCambodia = cambodia.intersection(
    ee.Geometry.Rectangle([-180, splitLat, 180, 90])
  );
  const southernCambodia = cambodia.intersection(
    ee.Geometry.Rectangle([-180, -90, 180, splitLat])
  );

  // 2. Data Acquisition
  const fireCollection = ee.ImageCollection('MODIS/051/MCD14ML')
    .filterDate(startDate, ee.Date(endDate).advance(1, 'day')) // Filter up to end of Feb 28
    .filterBounds(cambodia); // Filter for the entire Cambodia first

  // Check if the fire collection is empty
  const initialFireCount = fireCollection.size().getInfo();
  if (initialFireCount === 0) {
    console.log(`No active fire detections found for ${countryName} between ${startDate} and ${endDate}.`);
    console.log("C1");
    return;
  }
  console.log(`Total initial fire images: ${initialFireCount}`);

  // We are interested in individual fire detections, which are represented as features in MCD14ML.
  // We need to flatten the collection to a FeatureCollection if we want to count individual points.
  // The MCD14ML dataset is already structured as an ImageCollection where each image has multiple bands,
  // but it represents the fire *pixels* on a grid. To count *detections*, we usually count the number of
  // non-null pixels in a relevant band like 'brightness'.
  // However, MCD14ML also acts like a FeatureCollection of points where each feature is a fire detection.
  // Let's iterate and extract the fire points.

  // Function to extract fire points from an MCD14ML image
  const extractFirePoints = function(image) {
    return image.select('latitude', 'longitude', 'brightness')
      .reduceToVectors({
        geometry: image.geometry(),
        crs: image.projection(),
        scale: 1000, // MODIS resolution
        geometryType: 'points',
        reducer: ee.Reducer.mean(), // Not really needed for points, but required
        labelProperty: 'fire_detection', // A property to identify this as a fire point
        maxPixels: 1e9
      })
      .filter(ee.Filter.notNull(['fire_detection'])); // Ensure valid detections
  };

  // Map over the image collection to get a collection of fire points
  const allFirePoints = fireCollection.map(extractFirePoints).flatten();

  const totalFirePointsCount = allFirePoints.size().getInfo();
  if (totalFirePointsCount === 0) {
    console.log("No valid fire detection points found after processing.");
    console.log("C2");
    return;
  }

  // 3. Process and Count Detections for Each Region
  const northernFires = allFirePoints.filterBounds(northernCambodia);
  const southernFires = allFirePoints.filterBounds(southernCambodia);

  const numNorthernFires = northernFires.size().getInfo();
  const numSouthernFires = southernFires.size().getInfo();

  // 4. Validation & Final Answer
  if (numNorthernFires === null || numSouthernFires === null) {
    console.log("Error: Could not retrieve fire counts for one or both regions.");
    console.log("C3");
    return;
  }

  console.log(`Northern Cambodia Fire Detections: ${numNorthernFires}`);
  console.log(`Southern Cambodia Fire Detections: ${numSouthernFires}`);

  if (numNorthernFires > numSouthernFires) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
